<script setup lang="ts">
import {computed,ref} from 'vue'
import {api,post} from '../api'
import {usePolling} from '../usePolling'
import {useMarketStore} from '../store'
import {number,percent,price,time} from '../format'
import {stateName,riskName,walletLines,priceInput} from '../watch'
import type {WatchView,WatchPoint,WatchConfig} from '../watch'
import PageIntro from '../components/PageIntro.vue'
import StatCard from '../components/StatCard.vue'
const store=useMarketStore();const watches=ref<WatchView[]>([]);const selected=ref<number|null>(null);const assetsQuery=ref('ARIA');const history=ref<WatchPoint[]>([]);const audit=ref<{asOf:string;status:string;reason:string}[]>([])
const busy=ref(false);const errorMessage=ref('');const message=ref('');const editorId=ref<number|null>(null);const editRevision=ref(0);const enabled=ref(true);const alerts=ref(false)
const cost=ref('');const target=ref('');const attention=ref('');const support=ref('');const resistance=ref('');const wallets=ref('')
async function load(signal?:AbortSignal){const [w]=await Promise.all([api<WatchView[]>('/api/watchlist',{signal}),store.refresh(signal)]);watches.value=w}
const {error}=usePolling(signal=>load(signal),5000)
const assetName=(id:number)=>store.assets.find(m=>m.instrument.assetId===id)?.instrument.symbol??`Asset ${id}`
const matches=computed(()=>{const q=assetsQuery.value.trim().toUpperCase();return q?store.assets.filter(m=>m.instrument.symbol.includes(q)).slice(0,15):[]})
const current=computed(()=>watches.value.find(w=>w.config.assetId===selected.value));const paused=computed(()=>watches.value.filter(w=>!w.config.enabled).length)
function edit(id:number){if(busy.value)return;editorId.value=id;const c=watches.value.find(w=>w.config.assetId===id)?.config;editRevision.value=c?.revision??0;enabled.value=c?.enabled??true;alerts.value=c?.enableAlerts??false;cost.value=c?.costPrice?.toString()??'';target.value=c?.targetPrice?.toString()??'';attention.value=c?.attentionPrice?.toString()??'';support.value=c?.supportPrice?.toString()??'';resistance.value=c?.resistancePrice?.toString()??'';wallets.value=c?.wallets.map(w=>`${w.chain} | ${w.address} | ${w.role}`).join('\n')??'';errorMessage.value='';message.value=''}
let requestId=0
async function detail(id:number){selected.value=id;history.value=[];audit.value=[];const request=++requestId;try{const h=await api<WatchPoint[]>(`/api/watchlist/${id}/history?limit=30`);if(request===requestId)history.value=h}catch(e){if(request===requestId)errorMessage.value=String(e)}}
async function run(work:()=>Promise<void>){if(busy.value)return;busy.value=true;errorMessage.value='';try{await work()}catch(e){errorMessage.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
const evaluate=()=>run(async()=>{watches.value=await post('/api/watchlist/evaluate')})
const save=()=>run(async()=>{if(editorId.value===null)return;const id=editorId.value;await api<WatchConfig>(`/api/watchlist/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({expectedRevision:editRevision.value,enabled:enabled.value,costPrice:priceInput(cost.value),targetPrice:priceInput(target.value),attentionPrice:priceInput(attention.value),supportPrice:priceInput(support.value),resistancePrice:priceInput(resistance.value),enableAlerts:alerts.value,wallets:walletLines(wallets.value)})});watches.value=await post('/api/watchlist/evaluate');editorId.value=null;message.value='配置已保存；价格提醒首次只建立基线，持续重大风险可立即进入提醒队列。';await detail(id)})
const check=()=>run(async()=>{if(selected.value===null)return;audit.value=await api(`/api/watchlist/${selected.value}/audit?limit=30`)})
</script>
<template><PageIntro eyebrow="WATCHTOWER · PERSONAL OBSERVATION" title="关注一个币，持续看清变化。" description="成本、关键价位和独立证据一起保存；风险优先于上涨判断。"><button class="replay-action" :disabled="busy" @click="evaluate">{{busy?'处理中…':'更新监控判断'}}</button></PageIntro><p v-if="error||errorMessage" class="radar-notice" role="alert">{{errorMessage||error}}</p><p v-if="message" class="radar-notice" role="status">{{message}}</p><p class="radar-notice">ARIA 成本 0.40 初始项来自规格书，是示例观察配置，不代表真实持仓。个人提醒默认关闭，系统不执行买卖。链上指标受身份、覆盖与历史基线约束；BSC 资金流已接入，地址归属及采集范围不足时保持 Unknown。</p>
<div class="stats"><StatCard label="自选观察" :value="watches.length" :foot="`运行 ${watches.length-paused} · 暂停 ${paused}`"/><StatCard label="风险上升 / 重大风险" :value="watches.filter(w=>w.result&&w.result.risk>=3).length" foot="风险判断优先于正面证据"/><StatCard label="个人提醒已开启" :value="watches.filter(w=>w.config.enableAlerts&&w.config.enabled).length" foot="另受全局 Windows Toast 开关约束"/><StatCard label="策略版本" value="1.2" foot="WatchTower · 链上输入按质量门槛接入"/></div>
<div class="section-heading"><h2>添加或编辑自选</h2></div><div class="market-panel"><div class="toolbar"><label class="search"><input v-model="assetsQuery" aria-label="搜索自选合约" placeholder="输入交易所合约，例如 ARIA"></label><span class="results">最多显示 15 个匹配</span></div><div class="toolbar"><button v-for="m in matches" :key="m.instrument.assetId" class="text-button" @click="edit(m.instrument.assetId)">{{m.instrument.symbol}} · {{watches.some(w=>w.config.assetId===m.instrument.assetId)?'编辑':'添加'}}</button><span v-if="!matches.length" class="muted">没有匹配的本地交易所合约。</span></div></div>
<section v-if="editorId!==null" class="detail"><div class="section-heading"><h2>{{assetName(editorId)}} · 监控配置</h2><button class="text-button" :disabled="busy" @click="editorId=null">取消编辑 ×</button></div><p>编辑版本 {{editRevision}}；修改与暂停会保留配置历史。钱包配置只提供观察线索；资金流分类须另在链上页面核对归属证据。</p><div class="mapping-form"><label>成本价<input v-model="cost" aria-label="监控成本价" inputmode="decimal" placeholder="可选"></label><label>目标价<input v-model="target" aria-label="监控目标价" inputmode="decimal" placeholder="上穿提醒"></label><label>关注价<input v-model="attention" aria-label="监控关注价" inputmode="decimal" placeholder="上穿提醒"></label><label>关键支撑<input v-model="support" aria-label="监控支撑价" inputmode="decimal"></label><label>关键压力<input v-model="resistance" aria-label="监控压力价" inputmode="decimal"></label><label class="full-width">项目 / 团队 / 投资人钱包<textarea v-model="wallets" aria-label="监控钱包地址" rows="3" placeholder="每行：bsc | 0x完整地址 | project&#10;支持 bsc / ethereum / base / arbitrum / polygon"></textarea></label></div><label class="checkbox"><input v-model="enabled" type="checkbox" aria-label="启用此项监控">启用此项监控</label><label class="checkbox"><input v-model="alerts" type="checkbox" aria-label="启用个人提醒">启用个人提醒（重大风险 / 风险上升 / 目标和关注价上穿）</label><p>保存后的价格提醒先建立基线；同一状态不反复提醒，默认每个标的 30 分钟冷却，首次升级重大风险可越过普通冷却。暂停或关闭个人提醒会取消尚未发送的队列项。</p><button class="replay-action" :disabled="busy" @click="save">保存监控配置</button></section>
<div class="section-heading radar-heading"><h2>自选观察台</h2><RouterLink to="/alerts">查看个人通知记录 →</RouterLink></div><div class="market-panel table-scroll"><table><thead><tr><th>合约 / 来源</th><th>价格 / 成本</th><th>相对成本涨跌</th><th>回到成本所需变化</th><th>趋势 / 阶段</th><th>策略状态 / 风险</th><th>提醒</th><th>操作</th></tr></thead><tbody><tr v-for="w in watches" :key="w.config.assetId"><td>{{assetName(w.config.assetId)}}<small>{{w.result?.exchange??'等待判断'}} · {{w.config.isSpecificationExample?'规格书示例':'自定义'}}</small></td><td>{{price(w.result?.price.value)}} / {{price(w.config.costPrice)}}<small>{{time(w.result?.price.sourceTime)}}</small></td><td>{{percent(w.result?.costReturnPercent)}}</td><td>{{percent(w.result?.toCostPercent)}}<small>负数表示当前价已高于成本</small></td><td>{{w.result?.trend??'Unknown'}} / {{w.result?.currentStage??'Unknown'}}</td><td>{{w.result?stateName(w.result.state):'等待判断'}}<small>{{w.result?riskName(w.result.risk):'Unknown'}} · 置信度 {{w.result?.confidence??0}}</small></td><td>{{!w.config.enabled?'已暂停':w.config.enableAlerts?'个人提醒开启':'个人提醒关闭'}}</td><td><button class="text-button" @click="detail(w.config.assetId)">依据 →</button><button class="text-button" @click="edit(w.config.assetId)">编辑</button></td></tr><tr v-if="!watches.length"><td colspan="8" class="empty">尚未建立自选配置；本地合约加载完成后可添加。</td></tr></tbody></table></div>
<section v-if="current" class="detail"><div class="section-heading"><h2>{{assetName(current.config.assetId)}} · 策略依据</h2><button class="text-button" @click="selected=null">收起 ×</button></div><p>判断时间 {{time(current.result?.asOf)}} · 价格源 {{current.result?.exchange}} / {{current.result?.nativeSymbol}} · {{current.result?.version}}</p><div class="detail-grid"><div v-for="[label,value] in [['趋势分',current.result?.trendScore],['衍生品分',current.result?.derivativeScore],['链上分',current.result?.onChainScore],['钱包风险',current.result?.walletRiskScore],['拥挤风险',current.result?.crowdingRisk]]" :key="String(label)"><span>{{label}}</span><strong>{{number(value as number|null|undefined,1)}}</strong></div></div><h3>已观测正面证据</h3><p v-for="r in current.result?.positiveReasons" :key="r">{{r}}</p><h3>风险与缺失证据</h3><p v-for="r in [...current.result?.riskReasons??[],...current.result?.missingEvidence??[]]" :key="r">{{r}}</p><h3>下一观察点</h3><p v-for="r in current.result?.nextTriggers" :key="r">{{r}}</p><p v-for="wallet in current.config.wallets" :key="wallet.chain+wallet.address">{{wallet.role}} · {{wallet.chain}} · {{wallet.address}} · 归属以核对标签为准</p><RouterLink :to="{path:'/mappings',query:{symbol:assetName(current.config.assetId)}}">核对资产身份 →</RouterLink><p><RouterLink to="/speculative">检查备用交易所身份及数据 →</RouterLink> · <RouterLink to="/onchain">核对链上分布与地址标签 →</RouterLink> · <RouterLink to="/flows">查看转账与区块证据 →</RouterLink></p>
<div class="section-heading"><h2>历史状态 · 最近 30 条</h2><button class="replay-action" :disabled="busy" @click="check">复核历史判断</button></div><div class="table-scroll"><table><thead><tr><th>时间</th><th>来源 / 价格</th><th>状态 / 风险</th><th>配置版本</th></tr></thead><tbody><tr v-for="h in history" :key="h.result.asOf"><td>{{time(h.result.asOf)}}</td><td>{{h.result.exchange}} · {{price(h.result.price.value)}}</td><td>{{stateName(h.result.state)}} / {{riskName(h.result.risk)}}</td><td>{{h.input.config.revision}}</td></tr></tbody></table></div><p v-if="audit.length">复核 {{audit.length}} 条 · 一致 {{audit.filter(a=>a.status==='Match').length}} · 其他 {{audit.filter(a=>a.status!=='Match').length}}</p><p v-for="a in audit.filter(a=>a.status!=='Match')" :key="a.asOf">{{time(a.asOf)}} · {{a.status}} · {{a.reason}}</p></section>
</template>
